fun interface Spec<T> {
    fun isSatisfiedBy(candidate: T): Boolean
    infix fun and(other: Spec<T>) = Spec<T> { isSatisfiedBy(it) && other.isSatisfiedBy(it) }
}

val overdue = Spec<Invoice> { it.daysPastDue >= 30 }
val collectable = overdue and Spec { it.noticesSent >= 3 && !it.inCollection }

val rows = invoices.filter(collectable::isSatisfiedBy)
